(7179993, 1102926, 124815, '<td valign="top">Excellent shot through the "tears" <strike>on the window</strike> of the windshield<br/> <br/>bump<br/>At fourth look I have to bump this to 9 - (when I cover the bit of enhanced sky of the top left I like the shot even more)</td>', 'Excellent shot through the "tears" on the window of the windshield bumpAt fourth look I have to bump this to 9 - (when I cover the bit of enhanced sky of the top left I like the shot even more)', '2014-02-22 14:35:35.000000', NULL, 1),
(7180013, 1102821, 25190, '<td valign="top">A well captured street shot good composition and contrast good sharpness and i like the processing ..Well done</td>', 'A well captured street shot good composition and contrast good sharpness and i like the processing ..Well done', '2014-02-22 14:48:07.000000', NULL, 1),
(7180027, 1102522, 68504, '<td valign="top">Michaelangelo''s David with sass, jazz, brio. a gem.</td>', 'Michaelangelo''s David with sass, jazz, brio. a gem.', '2014-02-22 15:26:27.000000', NULL, 1),
