(7180032, 1102184, 68504, '<td valign="top">love it.</td>', 'love it.', '2014-02-22 15:29:45.000000', NULL, 1),
(7180033, 1102184, 18367, '<td valign="top">Funny how some images immediately make you think of a place you visited.  This image reminds me ever so much of a recent visit to Tasmania.<br/> <br/>I do find this a very appealing image and her is hoping you do well in the challenge.</td>', 'Funny how some images immediately make you think of a place you visited.  This image reminds me ever so much of a recent visit to Tasmania. I do find this a very appealing image and her is hoping you do well in the challenge.', '2014-02-22 15:32:28.000000', NULL, 1),
(7180034, 1102699, 68504, '<td valign="top">dynamic composition. all the energies sucked into the nearly empty carpark.</td>', 'dynamic composition. all the energies sucked into the nearly empty carpark.', '2014-02-22 15:32:39.000000', NULL, 1),
(7180035, 1102269, 68504, '<td valign="top">lovely composition. the concentrated energies pulled down and out of the frame.</td>', 'lovely composition. the concentrated energies pulled down and out of the frame.', '2014-02-22 15:34:17.000000', NULL, 1),
(7180036, 1102454, 68504, '<td valign="top">he is. beautiful set up.</td>', 'he is. beautiful set up.', '2014-02-22 15:34:56.000000', NULL, 1),
(7180041, 1102787, 68504, '<td valign="top">ya, Alma, bubbles trumps Pekes..</td>', 'ya, Alma, bubbles trumps Pekes..', '2014-02-22 15:54:42.000000', NULL, 1),
(7180076, 1102787, 27421, '<td valign="top">One I think Garry would have been proud of... my favorite and highest score. 10<br/>Good luck.....</td>', 'One I think Garry would have been proud of... my favorite and highest score. 10Good luck.....', '2014-02-22 19:12:06.000000', NULL, 1),
(7180077, 1102714, 27421, '<td valign="top">One of my top 3....9..... good luck.</td>', 'One of my top 3....9..... good luck.', '2014-02-22 19:12:52.000000', NULL, 1),
(7180078, 1102915, 27421, '<td valign="top">One of my top 3 choices....8..... Good luck.</td>', 'One of my top 3 choices....8..... Good luck.', '2014-02-22 19:13:25.000000', NULL, 1),
(7180108, 1102915, 94815, '<td valign="top">Almost too sentimental for Winogrand but very good candid shot.</td>', 'Almost too sentimental for Winogrand but very good candid shot.', '2014-02-22 20:57:03.000000', NULL, 1),
(7180109, 1102381, 94815, '<td valign="top">Capturing social classes and candid cynicism fits Winogrand well.</td>', 'Capturing social classes and candid cynicism fits Winogrand well.', '2014-02-22 20:58:25.000000', NULL, 1),
(7180111, 1102923, 94815, '<td valign="top">Worn out enthusiasm for traditional events in a cynical age. It''s all part of his work.</td>', 'Worn out enthusiasm for traditional events in a cynical age. It''s all part of his work.', '2014-02-22 21:02:50.000000', NULL, 1),
(7180114, 1102454, 94815, '<td valign="top">Nice juxtaposition of sign and figure keeps the humanity felt even as subverted into the system.</td>', 'Nice juxtaposition of sign and figure keeps the humanity felt even as subverted into the system.', '2014-02-22 21:05:36.000000', NULL, 1),
(7180116, 1102908, 94815, '<td valign="top">Well seen spontaneous instant inevitably lost except for this rare capture means more than the chuckle.</td>', 'Well seen spontaneous instant inevitably lost except for this rare capture means more than the chuckle.', '2014-02-22 21:08:33.000000', NULL, 1),
(7180118, 1102901, 94815, '<td valign="top">So prominent in street life now updated from the Winogrand style.</td>', 'So prominent in street life now updated from the Winogrand style.', '2014-02-22 21:10:35.000000', NULL, 1),
(7180120, 1102793, 94815, '<td valign="top">Maybe more playful and happy than the Winogrand I know but has some of his spontaneity.</td>', 'Maybe more playful and happy than the Winogrand I know but has some of his spontaneity.', '2014-02-22 21:12:48.000000', NULL, 1),
(7180121, 1102274, 94815, '<td valign="top">The painted patterns enhance the Winogrand tilt and spontaneity.</td>', 'The painted patterns enhance the Winogrand tilt and spontaneity.', '2014-02-22 21:14:04.000000', NULL, 1),
(7180122, 1102816, 94815, '<td valign="top">Good timing. Thanks for the chuckle.</td>', 'Good timing. Thanks for the chuckle.', '2014-02-22 21:14:28.000000', NULL, 1),
(7180124, 1102926, 94815, '<td valign="top">Effectively captured from a moving vehicle Winogrand style.</td>', 'Effectively captured from a moving vehicle Winogrand style.', '2014-02-22 21:17:56.000000', NULL, 1),
(7180126, 1102896, 94815, '<td valign="top">If Winogrand were in this place he might have grabbed this shot although there is more sympathy here (like Cartier-Bresson) than I myself see in Winogrand.</td>', 'If Winogrand were in this place he might have grabbed this shot although there is more sympathy here (like Cartier-Bresson) than I myself see in Winogrand.', '2014-02-22 21:20:45.000000', NULL, 1),
(7180131, 1102791, 94815, '<td valign="top">Striking. This could be a portrait of the man himself from what I''ve read and seen.</td>', 'Striking. This could be a portrait of the man himself from what I''ve read and seen.', '2014-02-22 21:31:43.000000', NULL, 1),
(7180132, 1102842, 94815, '<td valign="top">Good timing and candid sensibility but the digital processing is anything but Winogrand.</td>', 'Good timing and candid sensibility but the digital processing is anything but Winogrand.', '2014-02-22 21:32:38.000000', NULL, 1),
(7180134, 1102829, 94815, '<td valign="top">Tired and bored seems to reflect something of his work. The noble shepherd dog works as a foil to that mood.</td>', 'Tired and bored seems to reflect something of his work. The noble shepherd dog works as a foil to that mood.', '2014-02-22 21:35:55.000000', NULL, 1),
(7180135, 1102870, 94815, '<td valign="top">Plodding through those memories. Keep the money in the pocketbook.</td>', 'Plodding through those memories. Keep the money in the pocketbook.', '2014-02-22 21:36:47.000000', NULL, 1),
(7180138, 1102401, 94815, '<td valign="top">Hard to imagine Winogrand out on a hunt but if he were, this could have been his lucky shot.</td>', 'Hard to imagine Winogrand out on a hunt but if he were, this could have been his lucky shot.', '2014-02-22 21:38:12.000000', NULL, 1),
(7180139, 1102869, 94815, '<td valign="top">Children''s artlessness before maturing into cynical adults in the Winogrand style.</td>', 'Children''s artlessness before maturing into cynical adults in the Winogrand style.', '2014-02-22 21:39:07.000000', NULL, 1),
(7180140, 1102841, 94815, '<td valign="top">Charming and lovingly captured shot of a real beauty.</td>', 'Charming and lovingly captured shot of a real beauty.', '2014-02-22 21:39:54.000000', NULL, 1),
(7180143, 1102893, 94815, '<td valign="top">The pov implies some improbable interaction between the child and bird which like so much in our meanderings doesn''t happen but leaves the what-if thought anyway.</td>', 'The pov implies some improbable interaction between the child and bird which like so much in our meanderings doesn''t happen but leaves the what-if thought anyway.', '2014-02-22 21:43:11.000000', NULL, 1),
(7180144, 1102488, 94815, '<td valign="top">A stripe lover and more. Effective candid with unexpected visual relationships among the seeming randomness.</td>', 'A stripe lover and more. Effective candid with unexpected visual relationships among the seeming randomness.', '2014-02-22 21:44:44.000000', NULL, 1),
(7180145, 1102739, 94815, '<td valign="top">Good street shot but very un-Winogrand style processing.</td>', 'Good street shot but very un-Winogrand style processing.', '2014-02-22 21:45:23.000000', NULL, 1),
(7180146, 1102890, 94815, '<td valign="top">A rare moment of generational humanity well captured.</td>', 'A rare moment of generational humanity well captured.', '2014-02-22 22:01:18.000000', NULL, 1),
(7180148, 1102882, 94815, '<td valign="top">Well seen and captured shot but it has a formal, organized quality and optimism that has more of the spirit of what''s his name Saturday Evening Post painter than the unvarnished and cynically spontaneous questioning of Winogrand.</td>', 'Well seen and captured shot but it has a formal, organized quality and optimism that has more of the spirit of what''s his name Saturday Evening Post painter than the unvarnished and cynically spontaneous questioning of Winogrand.', '2014-02-22 22:07:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7180149, 1102301, 94815, '<td valign="top">From shadow to shadow. Well seen but lacks a Winogrand feeling and pov as far as I can see.</td>', 'From shadow to shadow. Well seen but lacks a Winogrand feeling and pov as far as I can see.', '2014-02-22 22:08:59.000000', NULL, 1),
(7180152, 1102812, 94815, '<td valign="top">She floats - and masterfully. A new Olympic event perhaps. These European shots never look like Winogrand but this has the film like quality.</td>', 'She floats - and masterfully. A new Olympic event perhaps. These European shots never look like Winogrand but this has the film like quality.', '2014-02-22 22:17:37.000000', NULL, 1),
(7180153, 1102583, 94815, '<td valign="top">A good candid underground street shot and maybe better without the title which is a stretch. Winogrand didn''t mess with titles much.</td>', 'A good candid underground street shot and maybe better without the title which is a stretch. Winogrand didn''t mess with titles much.', '2014-02-22 22:19:08.000000', NULL, 1),
(7180154, 1102853, 94815, '<td valign="top">Good close candid of a Winogrand subject but I think is might have been a throwaway except in his private album of women. She''s too self-content to be publishable among his parade of lost humanity.</td>', 'Good close candid of a Winogrand subject but I think is might have been a throwaway except in his private album of women. She''s too self-content to be publishable among his parade of lost humanity.', '2014-02-22 22:24:19.000000', NULL, 1),
(7180156, 1102556, 94815, '<td valign="top">Youth at ease before becoming alienated and cynical. Not so Winograndish but well done.</td>', 'Youth at ease before becoming alienated and cynical. Not so Winograndish but well done.', '2014-02-22 22:27:46.000000', NULL, 1),
(7180157, 1102269, 94815, '<td valign="top">Barren and beyond Winogrand as if he were looking back knowingly from the grave.</td>', 'Barren and beyond Winogrand as if he were looking back knowingly from the grave.', '2014-02-22 22:29:39.000000', NULL, 1),
(7180160, 1102685, 94815, '<td valign="top">Candid camera a bit more than Winogrand. Documentary shot which misses the evidence. I like the light effects like old film.</td>', 'Candid camera a bit more than Winogrand. Documentary shot which misses the evidence. I like the light effects like old film.', '2014-02-22 22:40:47.000000', NULL, 1),
(7180161, 1102802, 94815, '<td valign="top">Reminds me of someone but cant think who - very up close and involved almost in a cinematic way. So close we want to pull back but grow to appreciate the opportunity to be so involved. Great shot.</td>', 'Reminds me of someone but cant think who - very up close and involved almost in a cinematic way. So close we want to pull back but grow to appreciate the opportunity to be so involved. Great shot.', '2014-02-22 22:42:57.000000', NULL, 1),
(7180162, 1102835, 94815, '<td valign="top">As a study of Winogrand-like society and human condition, this works well but the postprocessing messing it up. Personally, I reworked mine several times before eliminating almost all digital processing to emulate Winogrand''s film.</td>', 'As a study of Winogrand-like society and human condition, this works well but the postprocessing messing it up. Personally, I reworked mine several times before eliminating almost all digital processing to emulate Winogrand''s film.', '2014-02-22 22:45:58.000000', NULL, 1),
(7180163, 1102895, 94815, '<td valign="top">Yup he was there. But this is so digitized that it is difficult to see it as a photograph.</td>', 'Yup he was there. But this is so digitized that it is difficult to see it as a photograph.', '2014-02-22 22:47:05.000000', NULL, 1),
(7180164, 1102830, 94815, '<td valign="top">Good try at a candid Winogrand shot but the color is too much to see through. Maybe if converted to black &amp; white.</td>', 'Good try at a candid Winogrand shot but the color is too much to see through. Maybe if converted to black & white.', '2014-02-22 22:51:11.000000', NULL, 1),
(7180165, 1102699, 94815, '<td valign="top">Good spontaneous shot but the processing is not very film like.</td>', 'Good spontaneous shot but the processing is not very film like.', '2014-02-22 22:52:21.000000', NULL, 1),
(7180166, 1102719, 94815, '<td valign="top">Lovely kid shot and post processing - but not very Winogrand in subject or processing or its formal composition.</td>', 'Lovely kid shot and post processing - but not very Winogrand in subject or processing or its formal composition.', '2014-02-22 22:53:40.000000', NULL, 1),
(7180167, 1102826, 94815, '<td valign="top">A spontaneous and poignant moment not so much within the Winogrand lexicon.</td>', 'A spontaneous and poignant moment not so much within the Winogrand lexicon.', '2014-02-22 22:54:30.000000', NULL, 1),
(7180170, 1102867, 100831, '<td valign="top">Love it... the spontaneousness of the characters and the three empty chairs. So much to take in.</td>', 'Love it... the spontaneousness of the characters and the three empty chairs. So much to take in.', '2014-02-22 23:19:04.000000', NULL, 1),
(7180171, 1102488, 100831, '<td valign="top">This is the best.. the interactions are priceless. The smoke, the casualness, and the laugh. Very well done. bump.</td>', 'This is the best.. the interactions are priceless. The smoke, the casualness, and the laugh. Very well done. bump.', '2014-02-22 23:20:53.000000', NULL, 1),
(7180174, 1102787, 94815, '<td valign="top">The survivors - a posthumous Winogrand collection - when he discovers that humanity has the will to survive and even to excel. Look at those bubbles! bump</td>', 'The survivors - a posthumous Winogrand collection - when he discovers that humanity has the will to survive and even to excel. Look at those bubbles! bump', '2014-02-22 23:27:38.000000', NULL, 1),
(7180177, 1102738, 94815, '<td valign="top">Could have come from his negatives except for the square crop. Good film-like quality as I recall it. This place seems so familiar but I can''t place it. voted earlier</td>', 'Could have come from his negatives except for the square crop. Good film-like quality as I recall it. This place seems so familiar but I can''t place it. voted earlier', '2014-02-22 23:31:20.000000', NULL, 1),
(7180179, 1102925, 94815, '<td valign="top">So very Garry Winogrand in the tilt and framing of this image of street people. The image itself impressive as a projection of Winogrand for the 21st century - could he have considered in his wildest imaginings that we might dress this way.</td>', 'So very Garry Winogrand in the tilt and framing of this image of street people. The image itself impressive as a projection of Winogrand for the 21st century - could he have considered in his wildest imaginings that we might dress this way.', '2014-02-22 23:37:13.000000', NULL, 1),
(7180181, 1102926, 23484, '<td valign="top">The building has turned too.</td>', 'The building has turned too.', '2014-02-22 23:43:06.000000', NULL, 1),
(7180182, 1102184, 23484, '<td valign="top">Beautiful composition.</td>', 'Beautiful composition.', '2014-02-22 23:43:33.000000', NULL, 1),
(7180183, 1102821, 94815, '<td valign="top">Yes he was drawn to women and this would have been an apt context. Very good street shot capturing here mood - so perfect as if staged.</td>', 'Yes he was drawn to women and this would have been an apt context. Very good street shot capturing here mood - so perfect as if staged.', '2014-02-22 23:43:45.000000', NULL, 1),
(7180184, 1102791, 23484, '<td valign="top">Great street shot and processing.</td>', 'Great street shot and processing.', '2014-02-22 23:43:54.000000', NULL, 1),
(7180185, 1102809, 94815, '<td valign="top">Captures the vibrancy of street sights more like Cartier-Bresson I think - instead of the cynicism of Winogrand. Good photo however.</td>', 'Captures the vibrancy of street sights more like Cartier-Bresson I think - instead of the cynicism of Winogrand. Good photo however.', '2014-02-22 23:44:14.000000', NULL, 1),
(7180186, 1102433, 23484, '<td valign="top">Everyday life at it''s best.</td>', 'Everyday life at it''s best.', '2014-02-22 23:44:40.000000', NULL, 1),
(7180190, 1102714, 94815, '<td valign="top">I don''t think Winogrand''s processing included borders like this but I''m not an expert so could be wrong. This is a well-felt and playful capture that is appealing in its own right - no need to imitate someone else. But what''s with the border?</td>', 'I don''t think Winogrand''s processing included borders like this but I''m not an expert so could be wrong. This is a well-felt and playful capture that is appealing in its own right - no need to imitate someone else. But what''s with the border?', '2014-02-22 23:55:05.000000', NULL, 1),
(7180192, 1102711, 94815, '<td valign="top">Good candid marred by those bleached artifacts like something from an old time photoscanner. I''m dying to see the exif.</td>', 'Good candid marred by those bleached artifacts like something from an old time photoscanner. I''m dying to see the exif.', '2014-02-22 23:56:15.000000', NULL, 1),
(7180194, 1102433, 94815, '<td valign="top">Great sequence of figures around the frame. Also good wide angle and involved point of view and spontaneous capture. It has a classic (say, Cartier-Bresson) pov and comp, which means unfortunately that it departs from the Winogrand random and more cynical esthetic. Overall, bump to a 7 only limited by the topicality. Love the image.</td>', 'Great sequence of figures around the frame. Also good wide angle and involved point of view and spontaneous capture. It has a classic (say, Cartier-Bresson) pov and comp, which means unfortunately that it departs from the Winogrand random and more cynical esthetic. Overall, bump to a 7 only limited by the topicality. Love the image.', '2014-02-23 00:00:41.000000', NULL, 1),
(7180198, 1102909, 94815, '<td valign="top">Unexpected associations and rhythms of the street fit well into the Winogrand opus. I chuckled at this even if I can''t say why.</td>', 'Unexpected associations and rhythms of the street fit well into the Winogrand opus. I chuckled at this even if I can''t say why.', '2014-02-23 00:31:37.000000', NULL, 1),
(7180201, 1102867, 94815, '<td valign="top">Affectingly felt juxtaposition of ordinary social-commercial activity and human emptiness. Bumping for its sympathy for the Winogrand esthetic.</td>', 'Affectingly felt juxtaposition of ordinary social-commercial activity and human emptiness. Bumping for its sympathy for the Winogrand esthetic.', '2014-02-23 00:32:58.000000', NULL, 1),
(7180202, 1102749, 94815, '<td valign="top">Class and place well captured in the Winogrand way. bump for that</td>', 'Class and place well captured in the Winogrand way. bump for that', '2014-02-23 00:33:16.000000', NULL, 1),
(7180204, 1102184, 94815, '<td valign="top">California coast as he might have shot it - this has some of his heart. Aside from that issue, its a great shot except possibly for the vignette which seems unnatural from a modern camera.</td>', 'California coast as he might have shot it - this has some of his heart. Aside from that issue, its a great shot except possibly for the vignette which seems unnatural from a modern camera.', '2014-02-23 00:35:38.000000', NULL, 1),
(7180206, 1102522, 94815, '<td valign="top">The telephoto compression doesn''t quite fit Winogrand''s wide angle style but the candid street capture nails it. The centered eyeball pulls me in (nicely) but distracts from the Winogrand esthetic. I''m bumping to a 7 which if, say, for the eyeball topic, could be a 9.</td>', 'The telephoto compression doesn''t quite fit Winogrand''s wide angle style but the candid street capture nails it. The centered eyeball pulls me in (nicely) but distracts from the Winogrand esthetic. I''m bumping to a 7 which if, say, for the eyeball topic, could be a 9.', '2014-02-23 00:38:39.000000', NULL, 1),
(7180209, 1102928, 94815, '<td valign="top">Nothing so intimate as the interaction with food. This is precious and maybe Winogrand-like although he might have missed it. Still..</td>', 'Nothing so intimate as the interaction with food. This is precious and maybe Winogrand-like although he might have missed it. Still..', '2014-02-23 00:40:49.000000', NULL, 1),
(7180210, 1102345, 94815, '<td valign="top">Nicely captured candid if not quite as spontaneous as Winogrand''s tilts.</td>', 'Nicely captured candid if not quite as spontaneous as Winogrand''s tilts.', '2014-02-23 00:41:07.000000', NULL, 1),
(7180211, 1102471, 94815, '<td valign="top">The crop is not conventional Winogrand but the spontaneity comes close. On its own, an intriguing candid image with implications of drama to be resolved.</td>', 'The crop is not conventional Winogrand but the spontaneity comes close. On its own, an intriguing candid image with implications of drama to be resolved.', '2014-02-23 00:43:07.000000', NULL, 1),
(7180212, 1102783, 94815, '<td valign="top">Looks like mugging for the camera but has something of the spontaneous spirit of Winogrand''s street shots.</td>', 'Looks like mugging for the camera but has something of the spontaneous spirit of Winogrand''s street shots.', '2014-02-23 00:43:41.000000', NULL, 1),
(7180213, 1102610, 94815, '<td valign="top">I don''t think of Winogrand as delivering such a deeply felt portrait, which is a shame. This has more of Dorothea Lange''s penetrating and heart-felt interest in humanity. Quite an involving, intimate, engagement with a living person - his uninhibited involvement with the camera is quite profound. The eyes are spectacular.</td>', 'I don''t think of Winogrand as delivering such a deeply felt portrait, which is a shame. This has more of Dorothea Lange''s penetrating and heart-felt interest in humanity. Quite an involving, intimate, engagement with a living person - his uninhibited involvement with the camera is quite profound. The eyes are spectacular.', '2014-02-23 00:50:13.000000', NULL, 1),
(7180214, 1102891, 94815, '<td valign="top">Effectively spontaneous (and ultimately powerful) capture - surreal in the poses of the two almost dance-like postures of the children where the girl seems to be disintegrating into the vending machine. Good subject and well organized composition very unlike Winogrand. More like Salvador Dali turned loose with a camera.</td>', 'Effectively spontaneous (and ultimately powerful) capture - surreal in the poses of the two almost dance-like postures of the children where the girl seems to be disintegrating into the vending machine. Good subject and well organized composition very unlike Winogrand. More like Salvador Dali turned loose with a camera.', '2014-02-23 00:53:45.000000', NULL, 1),
(7180250, 1102739, 124190, '<td valign="top">Austin is one place I have been where I signed more petitions and had more discussions and debates than anywhere else.  A vital city and great place to live.  Nice shot.</td>', 'Austin is one place I have been where I signed more petitions and had more discussions and debates than anywhere else.  A vital city and great place to live.  Nice shot.', '2014-02-23 08:40:39.000000', NULL, 1),
(7180251, 1102882, 124190, '<td valign="top">Beautiful. This really makes me miss my son....I used to carry him like this and he had that same kind of cute squinty expression...... wonderful.   I''m in tears.</td>', 'Beautiful. This really makes me miss my son....I used to carry him like this and he had that same kind of cute squinty expression...... wonderful.   I''m in tears.', '2014-02-23 08:45:06.000000', NULL, 1),
(7180252, 1102901, 124190, '<td valign="top">I will have the grilled prawns with mango and the veggie curry/coconut please!</td>', 'I will have the grilled prawns with mango and the veggie curry/coconut please!', '2014-02-23 08:47:30.000000', NULL, 1),
(7180253, 1102783, 124190, '<td valign="top">Yes, yes even you can be caught. Lol....love that incredulous expression!</td>', 'Yes, yes even you can be caught. Lol....love that incredulous expression!', '2014-02-23 08:48:37.000000', NULL, 1),
(7180254, 1102926, 124190, '<td valign="top">I supposed cell phone repair will do it.   Have you noticed how many shots in this challenge have people on cell phones?   Now they know where to go if they break!  Great shot, like the rain blurs.</td>', 'I supposed cell phone repair will do it.   Have you noticed how many shots in this challenge have people on cell phones?   Now they know where to go if they break!  Great shot, like the rain blurs.', '2014-02-23 08:52:14.000000', NULL, 1),
(7180255, 1102812, 124190, '<td valign="top">I want to know where this is!  Looks fun.</td>', 'I want to know where this is!  Looks fun.', '2014-02-23 08:53:08.000000', NULL, 1),
(7180256, 1102869, 124190, '<td valign="top">Precious!</td>', 'Precious!', '2014-02-23 08:55:11.000000', NULL, 1),
